import java.util.Arrays;

class Solution {
    public int minStickers(String[] stickers, String target) {
            int n = target.length();
                    int maxMask = 1 << n;
                            
                                    // dp[mask] represents the minimum stickers needed to form the subset of characters in mask
                                            int[] dp = new int[maxMask];
                                                    Arrays.fill(dp, -1);
                                                            dp[0] = 0; // Base case: 0 stickers needed to form an empty target

                                                                    // Precompute character frequencies for each sticker
                                                                            int m = stickers.length;
                                                                                    int[][] stickerCounts = new int[m][26];
                                                                                            for (int i = 0; i < m; i++) {
                                                                                                        for (char c : stickers[i].toCharArray()) {
                                                                                                                        stickerCounts[i][c - 'a']++;
                                                                                                                                    }
                                                                                                                                            }

                                                                                                                                                    // Iterate through all bitmasks
                                                                                                                                                            for (int mask = 0; mask < maxMask; mask++) {
                                                                                                                                                                        if (dp[mask] == -1) continue;

                                                                                                                                                                                    for (int i = 0; i < m; i++) {
                                                                                                                                                                                                    // Optimization: only use sticker if it can satisfy the first uncovered character
                                                                                                                                                                                                                    // Find the first unset bit in mask
                                                                                                                                                                                                                                    int firstUnset = -1;
                                                                                                                                                                                                                                                    for (int j = 0; j < n; j++) {
                                                                                                                                                                                                                                                                        if (((mask >> j) & 1) == 0) {
                                                                                                                                                                                                                                                                                                firstUnset = j;
                                                                                                                                                                                                                                                                                                                        break;
                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                            if (firstUnset == -1) break; // All bits are covered

                                                                                                                                                                                                                                                                                                                                                                                                            // If this sticker does not contain the needed first character, skip it
                                                                                                                                                                                                                                                                                                                                                                                                                            if (stickerCounts[i][target.charAt(firstUnset) - 'a'] == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Apply the sticker to advance the mask
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int nextMask = mask;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int[] count = stickerCounts[i].clone();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int j = 0; j < n; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (((nextMask >> j) & 1) == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            char c = target.charAt(j);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (count[c - 'a'] > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                count[c - 'a']--;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            nextMask |= (1 << j);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (dp[nextMask] == -1 || dp[nextMask] > dp[mask] + 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dp[nextMask] = dp[mask] + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return dp[maxMask - 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }